if score == 3 and name == "Ada" or false:
C
end
if not (score > 5 or score < 0):
D
end
{if score > 2}E{if score > 100}x{else}F{end}G{else}H{end}
{score > 2 | big | small} {score | truthy | falsy} {name == "Bob" | bob}
